nested_complex.query:
db.restaurants.aggregate([
  { $match: { cuisine: 'Italian' } },
  { $unwind: '$grades' },
  { $match: { 'grades.grade': 'A', 'grades.score': { $lt: 10 } } },
  { $group: {
      _id: '$name',
      name: { $first: '$name' },
      address: { $first: '$address' }
  } },
  { $sort: { name: 1 } },
  { $limit: 10 },
  { $project: { _id: 0, name: 1, address: 1 } }
])

non_nested_complex.query:
db.planets.aggregate([
  {
    $match: {
      mainAtmosphere: { $all: ["CO2", "N"] }
    }
  },
  {
    $project: {
      _id: 0,
      name: 1,
      mainAtmosphere: 1,
      surfaceTemperatureC: 1,
      hasRings: 1
    }
  }
])
